from edit import *
q=load(30);bi(q['caseStudy']['title'],'Chest pain with acute ST-segment changes','胸痛伴急性 ST 段变化');p=part(q,'q2');p['ngnSkill']='analyze_cues';bi(p['clozeStem'],'The new findings suggest {{1}}, requiring {{2}}.','新发现提示 {{1}}，需要 {{2}}。');p['dropdowns'][0]['options'].append({'id':'o3',**pair('Isolated hypovolemia without pump failure','不伴泵衰竭的单纯低血容量')});bi(obj(p['dropdowns'][1]['options'],'o1'),'urgent shock-team escalation and coronary reperfusion evaluation with prescribed hemodynamic support','紧急启动休克团队并评估冠脉再灌注，同时按医嘱提供血流动力学支持');bi(obj(p['dropdowns'][1]['options'],'o2'),'antibiotics alone while deferring cardiac intervention','仅用抗生素并推迟心脏干预');p['dropdowns'][1]['options'].append({'id':'o3',**pair('routine observation until the next scheduled vital-sign check','常规观察至下一次计划生命体征检查')});bi(p['rationale']['correct'],'AMI followed by severe hypotension, tachycardia and diffuse crackles suggests pump failure with cardiogenic shock. Escalate immediately for shock management and urgent coronary reperfusion assessment. Prescribed vasoactive support may be needed to maintain perfusion while the cause is treated; inotropes alone are not definitive treatment.','AMI 后出现严重低血压、心动过速及弥漫湿啰音，提示泵衰竭并心源性休克。应立即升级至休克处理并紧急评估冠脉再灌注。在治疗病因的同时，可能需按医嘱使用血管活性药维持灌注；仅用正性肌力药并非确定性治疗。');p['rationale']['byChoice']=[{'refId':'1',**pair('In this AMI context, hypotension with pulmonary congestion supports cardiogenic shock over isolated hypovolemia; the record does not establish an infectious cause.','在此 AMI 背景下，低血压伴肺淤血比单纯低血容量更支持心源性休克；记录未确立感染病因。')},{'refId':'2',**pair('Urgent reperfusion assessment and monitored hemodynamic support address the cause and perfusion threat. Antibiotics alone and delayed routine observation do not.','紧急再灌注评估和监测下的血流动力学支持可处理病因及灌注威胁；仅用抗生素或延后常规观察不能解决。')}];anchor(p,'stage_1');save(q)
q=load(37);bi(q['caseStudy']['title'],'Acute cardiac and hepatic abnormalities during combination immunotherapy','联合免疫治疗期间的急性心脏和肝脏异常');p=part(q,'q2');bi(p['rationale']['correct'],'New conduction and diffuse ST changes, elevated cardiac injury markers, and symptoms during combination ICI therapy make ICI myocarditis the leading urgent hypothesis. Concurrent immune-mediated hepatitis is suspected, but transaminase elevation does not establish its cause. Known hepatic metastases, other liver disease and infection require assessment; cardiology must also evaluate acute coronary syndrome.','联合 ICI 治疗期间出现新发传导及弥漫 ST 改变、心肌损伤标志物升高和症状，使 ICI 心肌炎成为最需紧急处理的首要假设。同时怀疑免疫介导性肝炎，但转氨酶升高不能确立病因。需评估已知肝转移、其他肝病及感染；心内科也必须评估急性冠脉综合征。');bi(obj(p['rationale']['byChoice'],'opt_mets','refId'),'Known metastases remain relevant, especially when evaluating the liver abnormalities. However, the new cardiac injury and conduction changes during ICI treatment require urgent evaluation for treatment-related myocarditis.','已知转移灶仍有临床意义，尤其在评估肝脏异常时。但 ICI 治疗期间新出现的心肌损伤和传导改变，需紧急评估治疗相关心肌炎。');bi(obj(p['rationale']['byChoice'],'opt_viral','refId'),'Viral myocarditis remains possible and needs appropriate exclusion; liver-enzyme elevation does not exclude infection. The treatment exposure and new cardiac findings prioritize ICI toxicity in this case.','病毒性心肌炎仍有可能，需适当排查；肝酶升高不能排除感染。此病例中的治疗暴露及新发心脏发现，使 ICI 毒性成为优先假设。');bi(obj(p['rationale']['byChoice'],'opt_ici_myocarditis','refId'),'This is the leading hypothesis requiring urgent specialist assessment; neither myocardial nor hepatic attribution is proved solely by elevated biomarkers.','这是需要紧急专科评估的首要假设；仅凭生物标志物升高不能证实心肌或肝脏病因。');bi(p['testTakingStrategy'],'Use treatment exposure and the pattern of new organ injury to prioritize hypotheses while keeping alternative causes under evaluation.','利用治疗暴露和新发器官损伤模式确定优先假设，同时继续评估其他病因。');anchor(p,'opus_icit_stage_1')
p=part(q,'q3');p['itemType']='select_all';p['ngnSkill']='take_action';bi(p['stem'],'At Stage 2, which actions should the nurse coordinate now in response to the urgent orders? Select all that apply.','在第 2 阶段，护士应根据紧急医嘱立即协调哪些措施？选择所有适用项。');p['options'].extend([{'id':'ord_wait_mri',**pair('Delay the first corticosteroid dose until tomorrow’s cardiac MRI confirms myocarditis.','推迟第一剂皮质类固醇，直到明天心脏 MRI 确认心肌炎。')},{'id':'ord_stop_monitor',**pair('Disconnect telemetry while waiting for a transfer bed because monitoring will resume on arrival.','等候转科床位期间断开心电监护，因为到达后会恢复监护。')}]);bi(p['rationale']['correct'],'Coordinate oxygenation, continuous monitoring and patent IV access, prompt prescribed high-dose corticosteroids, and preparation for monitored transfer. These urgent tasks can proceed concurrently with team assistance. IV access is required for IV administration; neither transfer logistics nor next-day imaging should delay time-critical treatment. Corticosteroids are first-line treatment, with ongoing reassessment for response or refractory disease.','应协调氧合、持续监护和畅通静脉通路，及时按医嘱给予高剂量皮质类固醇，并准备有监护的转运。这些紧急任务可在团队协助下并行进行。静脉给药需要静脉通路；转科安排或次日影像检查都不应延误具有时效性的治疗。皮质类固醇是一线治疗，仍需不断复评疗效或难治性病情。');bi(obj(p['rationale']['byChoice'],'ord_transfer','refId'),'Prepare monitored transfer in parallel with immediate care; maintain monitoring and treatment throughout the transition.','在立即照护的同时准备有监护的转运；转运过程中保持监护及治疗。');p['rationale']['byChoice'].extend([{'refId':'ord_wait_mri',**pair('Probable ICI myocarditis with deterioration warrants prompt prescribed treatment; imaging must not delay the first dose.','疑似 ICI 心肌炎伴恶化需要及时按医嘱治疗；不能因影像检查而推迟第一剂。')},{'refId':'ord_stop_monitor',**pair('New conduction changes and frequent PVCs require uninterrupted monitoring during transfer preparation.','新发传导改变和频发室早要求在转运准备期间持续监护。')}]);bi(p['testTakingStrategy'],'Identify real prerequisites and coordinate urgent care in parallel. Preserve oxygenation and monitoring while initiating time-critical treatment and arranging transfer.','识别真正的前提条件，协调并行紧急照护。在启动具有时效性的治疗和安排转运时保持氧合与监护。');anchor(p,'opus_icit_stage_2');c=content(q,1);rep(c,'en',' The nurse administers the first dose of methylprednisolone and titrates oxygen to 3 L/min via nasal cannula, achieving SpO₂ 95%.','');rep(c,'zh','护士给药第一剂甲泼尼龙，并将鼻导管吸氧滴定至3 L/min，使SpO₂达到95%。','');rep(c,'zh','心电监护降级病房','心脏监护中间护理病房');save(q)
